`timescale 1ns/1ps
module tb;reg clk=0,rst_n=0,restart=0,authorize=0,candidates_distinct=1,observation_valid=0;reg[7:0]request_mask=0,request_value=0,observed_response=0;reg[143:0]a=0,b=0;wire probe_valid,transmit,candidate_a_survives,candidate_b_survives,observation_resolved,observation_contradiction;wire[7:0]probe_request;reg[3:0]address;wire[7:0]data;always#5 clk=~clk;
active_probe_controller p(.clk(clk),.rst_n(rst_n),.restart(restart),.request_mask(request_mask),.request_value(request_value),.candidate_a(a),.candidate_b(b),.candidates_distinct(candidates_distinct),.authorize(authorize),.observation_valid(observation_valid),.observed_response(observed_response),.probe_valid(probe_valid),.probe_request(probe_request),.transmit(transmit),.candidate_a_survives(candidate_a_survives),.candidate_b_survives(candidate_b_survives),.observation_resolved(observation_resolved),.observation_contradiction(observation_contradiction));
mindreader_status s(.address(address),.supervisor_state(3),.fault_reason(2),.physical_complete(1),.direction_resolved(1),.model_valid(1),.stream_causal(1),.timing_safe(1),.ownership_granted(0),.evidence_count(8),.survivor_count(16'h1234),.probe_kind(3),.trace_overflow(1),.contradiction(0),.contention(1),.data(data));
task tick;begin @(posedge clk);#1;end endtask task fail;input[399:0]x;begin $display("FAIL %0s",x);$finish(1);end endtask
integer i;initial begin for(i=0;i<8;i=i+1)begin a[i*18+0]=1;b[i*18+0]=1;end b[0]=0;b[1]=1;repeat(2)tick();rst_n=1;tick();if(!probe_valid||probe_request!=0)fail("proposal");observation_valid=1;observed_response=1;tick();observation_valid=0;if(observation_resolved||!candidate_a_survives||!candidate_b_survives)fail("unauthorized observation changed candidates");tick();if(transmit)fail("unauthorized");authorize=1;tick();if(!transmit)fail("authorized");authorize=0;observed_response=1;observation_valid=1;tick();observation_valid=0;if(!observation_resolved||candidate_a_survives||!candidate_b_survives||observation_contradiction)fail("observation did not eliminate candidate");restart=1;candidates_distinct=0;tick();restart=0;if(probe_valid)fail("identical");address=2;#1;if(data!=8'b11111001)fail("flags");address=4;#1;if(data!=8'h34)fail("survivors");address=7;#1;if(data!=1)fail("overflow");$display("PROBE STATUS PASS");$finish(0);end endmodule
